const clean = (value, max) => String(value ?? '').replace(/\s+/g, ' ').trim().slice(0, max);

const plannedVideoTitle = clean($json.planned_video_title, 140);
const videoPromise = clean($json.video_promise, 600);
const audience = clean($json.audience, 120);
const targetKeyword = clean($json.target_keyword, 100);
const brandPalette = clean($json.brand_palette, 120) || 'high contrast, channel-consistent colors';
const thumbnailText = clean($json.thumbnail_text, 40);
const rawUrls = [
  clean($json.competitor_url_1, 300),
  clean($json.competitor_url_2, 300),
  clean($json.competitor_url_3, 300),
].filter(Boolean);

const extractYouTubeId = (value) => {
  const patterns = [
    /^https:\/\/(?:www\.|m\.)?youtube\.com\/watch\?(?:[^#]*&)?v=([A-Za-z0-9_-]{11})(?:[&#]|$)/i,
    /^https:\/\/youtu\.be\/([A-Za-z0-9_-]{11})(?:[?&#/]|$)/i,
    /^https:\/\/(?:www\.|m\.)?youtube\.com\/(?:shorts|embed)\/([A-Za-z0-9_-]{11})(?:[?&#/]|$)/i,
  ];
  for (const pattern of patterns) {
    const match = value.match(pattern);
    if (match) return match[1];
  }
  return '';
};

const errors = [];
if (!plannedVideoTitle) errors.push('Planned video title is required.');
if (!videoPromise) errors.push('Video promise is required.');
if (!audience) errors.push('Audience is required.');
if (!targetKeyword) errors.push('Target keyword is required.');
if (thumbnailText && thumbnailText.split(/\s+/).filter(Boolean).length > 4) {
  errors.push('Thumbnail text must contain four words or fewer.');
}
if (rawUrls.length < 2) errors.push('Add at least two public competitor YouTube URLs.');

const competitors = [];
const seen = new Set();
for (const sourceUrl of rawUrls) {
  const videoId = extractYouTubeId(sourceUrl);
  if (!videoId) {
    errors.push('Unsupported YouTube URL: ' + sourceUrl);
    continue;
  }
  if (seen.has(videoId)) continue;
  seen.add(videoId);
  competitors.push({
    video_id: videoId,
    source_url: 'https://www.youtube.com/watch?v=' + videoId,
    thumbnail_url: 'https://i.ytimg.com/vi/' + videoId + '/hqdefault.jpg',
    oembed_url: 'https://www.youtube.com/oembed?url=' + encodeURIComponent('https://www.youtube.com/watch?v=' + videoId) + '&format=json',
  });
}
if (rawUrls.length >= 2 && competitors.length < 2) {
  errors.push('Add at least two unique, supported YouTube video URLs.');
}

return [{
  json: {
    valid: errors.length === 0,
    errors,
    planned_video_title: plannedVideoTitle,
    video_promise: videoPromise,
    audience,
    target_keyword: targetKeyword,
    brand_palette: brandPalette,
    thumbnail_text: thumbnailText,
    aspect_ratio: '16:9',
    competitors,
    submitted_at: $json.submittedAt || new Date().toISOString(),
    workflow_version: '2.0.0',
  },
}];

const brief = $json;
return brief.competitors.map((competitor, index) => ({
  json: {
    ...competitor,
    competitor_number: index + 1,
    planned_video_title: brief.planned_video_title,
    video_promise: brief.video_promise,
    audience: brief.audience,
    target_keyword: brief.target_keyword,
    brand_palette: brief.brand_palette,
    thumbnail_text: brief.thumbnail_text,
    aspect_ratio: brief.aspect_ratio,
    submitted_at: brief.submitted_at,
    workflow_version: brief.workflow_version,
    openai_model: brief.openai_model,
    thumbcanvas_base_url: brief.thumbcanvas_base_url,
  },
}));

const job = $('Prepare Competitor Jobs').item.json;
const statusCode = Number($json.statusCode ?? 0);
const body = $json.body && typeof $json.body === 'object' ? $json.body : {};
const metadataOk = statusCode >= 200 && statusCode < 300 && Boolean(body.title);

return {
  json: {
    ...job,
    metadata_ok: metadataOk,
    metadata_status: statusCode || 'request_error',
    source_title: String(body.title || 'Metadata unavailable').slice(0, 240),
    author_name: String(body.author_name || 'Unknown channel').slice(0, 160),
    author_url: String(body.author_url || '').slice(0, 300),
    thumbnail_url: String(body.thumbnail_url || job.thumbnail_url).slice(0, 500),
  },
};

const source = $('Combine Public YouTube Metadata').item.json;
const output = Array.isArray($json.output) ? $json.output : [];
let structured = null;

for (const item of output) {
  if (!item || item.type !== 'message' || !Array.isArray(item.content)) continue;
  const textPart = item.content.find((part) => part && part.type === 'output_text');
  if (!textPart) continue;
  if (textPart.text && typeof textPart.text === 'object') {
    structured = textPart.text;
  } else if (typeof textPart.text === 'string') {
    try {
      structured = JSON.parse(textPart.text);
    } catch (error) {
      structured = null;
    }
  }
}

const requiredStrings = ['focal_subject', 'composition', 'contrast', 'emotion', 'visual_hook'];
const validShape = structured &&
  requiredStrings.every((key) => typeof structured[key] === 'string') &&
  Array.isArray(structured.visible_text) &&
  Array.isArray(structured.copy_risks) &&
  Array.isArray(structured.transferable_patterns) &&
  Array.isArray(structured.limitations);

return {
  json: {
    video_id: source.video_id,
    source_url: source.source_url,
    thumbnail_url: source.thumbnail_url,
    source_title: source.source_title,
    author_name: source.author_name,
    metadata_ok: source.metadata_ok,
    analysis_ok: Boolean(validShape),
    analysis: validShape ? structured : null,
    analysis_error: validShape ? '' : String($json.error?.message || $json.error || 'OpenAI did not return the required analysis schema').slice(0, 500),
  },
};

const aggregate = $('Aggregate Competitor Evidence').first().json;
const output = Array.isArray($json.output) ? $json.output : [];
let structured = null;

for (const item of output) {
  if (!item || item.type !== 'message' || !Array.isArray(item.content)) continue;
  const textPart = item.content.find((part) => part && part.type === 'output_text');
  if (!textPart) continue;
  if (textPart.text && typeof textPart.text === 'object') {
    structured = textPart.text;
  } else if (typeof textPart.text === 'string') {
    try {
      structured = JSON.parse(textPart.text);
    } catch (error) {
      structured = null;
    }
  }
}

const concepts = Array.isArray(structured?.concepts) ? structured.concepts : [];
const conceptsReady = concepts.length === 3 && concepts.every((concept, index) =>
  Number(concept.id) === index + 1 &&
  typeof concept.name === 'string' &&
  typeof concept.evidence === 'string' &&
  typeof concept.prompt === 'string' &&
  Array.isArray(concept.source_video_ids) &&
  Array.isArray(concept.risks)
);

const escapeHtml = (value) => {
  const chars = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
  return String(value ?? '').replace(/[&<>"']/g, (char) => chars[char]);
};

let reviewHtml = '';
if (conceptsReady) {
  const sourceHtml = aggregate.usable_evidence.map((source) => [
    '<article>',
    '<p><img src="' + escapeHtml(source.thumbnail_url) + '" width="360" alt="Competitor thumbnail"></p>',
    '<p><strong>' + escapeHtml(source.source_title) + '</strong><br>',
    escapeHtml(source.author_name) + ' · <a href="' + escapeHtml(source.source_url) + '" target="_blank">Open source video</a></p>',
    '</article>',
  ].join('')).join('<hr>');

  const conceptHtml = concepts.map((concept) => [
    '<article>',
    '<h3>' + escapeHtml(concept.id) + '. ' + escapeHtml(concept.name) + '</h3>',
    '<p><strong>Evidence:</strong> ' + escapeHtml(concept.evidence) + '</p>',
    '<p><strong>On-image text:</strong> ' + escapeHtml(concept.headline_text || 'None') + '</p>',
    '<p><strong>Composition:</strong> ' + escapeHtml(concept.composition) + '</p>',
    '<p><strong>Palette:</strong> ' + escapeHtml(concept.palette) + '</p>',
    '<p><strong>Source IDs:</strong> ' + escapeHtml(concept.source_video_ids.join(', ')) + '</p>',
    '<p><strong>Risks to review:</strong> ' + escapeHtml(concept.risks.join('; ') || 'None noted') + '</p>',
    '</article>',
  ].join('')).join('<hr>');

  reviewHtml = [
    '<h2>Evidence reviewed</h2>',
    '<p>Open the public sources and compare them with the structured observations. OpenAI vision can make mistakes, especially with small text; your approval is required.</p>',
    sourceHtml,
    '<h2>Three original directions</h2>',
    '<p><strong>Shared pattern summary:</strong> ' + escapeHtml((structured.patterns_summary || []).join('; ')) + '</p>',
    conceptHtml,
    '<p>No ThumbCanvas link exists yet. The workflow creates one only after you approve a concept below.</p>',
  ].join('');
}

return [{
  json: {
    ...aggregate,
    concepts_ready: conceptsReady,
    concepts,
    patterns_summary: Array.isArray(structured?.patterns_summary) ? structured.patterns_summary : [],
    review_html: reviewHtml,
    concept_error: conceptsReady ? '' : String($json.error?.message || $json.error || 'OpenAI did not return exactly three schema-valid concepts').slice(0, 500),
  },
}];

const pack = $('Parse Concepts and Build Review').first().json;
const decision = String($json.approval_decision || '').trim();
const reviewNotes = String($json.review_notes || '').replace(/\s+/g, ' ').trim().slice(0, 500);
const match = decision.match(/^Approve concept ([123])$/);
const approved = Boolean(match);

if (!approved) {
  return [{ json: {
    approved: false,
    decision: decision || 'Reject all concepts',
    review_notes: reviewNotes,
    planned_video_title: pack.planned_video_title,
  } }];
}

const concept = pack.concepts[Number(match[1]) - 1];
const query = [
  ['prompt', concept.prompt],
  ['aspect', pack.aspect_ratio],
].map((entry) => encodeURIComponent(entry[0]) + '=' + encodeURIComponent(String(entry[1]))).join('&');
const thumbcanvasUrl = pack.thumbcanvas_base_url + '?' + query;

return [{
  json: {
    approved: true,
    approved_concept: concept,
    review_notes: reviewNotes,
    thumbcanvas_url: thumbcanvasUrl,
    audit_row: {
      approved_at: new Date().toISOString(),
      planned_video_title: pack.planned_video_title,
      target_keyword: pack.target_keyword,
      audience: pack.audience,
      competitor_urls: pack.usable_evidence.map((source) => source.source_url).join('\n'),
      approved_concept: concept.name,
      concept_evidence: concept.evidence,
      thumbcanvas_url: thumbcanvasUrl,
      openai_model: pack.openai_model,
      analysis_status: pack.analysis_status,
      review_notes: reviewNotes,
      workflow_version: pack.workflow_version,
    },
  },
}];

const approval = $('Resolve Human Approval').first().json;
const errorMessage = String($json.error?.message || $json.error || '').slice(0, 500);
return [{
  json: {
    ...approval,
    sheet_write_ok: !errorMessage,
    sheet_error: errorMessage,
  },
}];
